package com.example.demo3;

import java.io.*;
import java.util.Arrays;
import java.util.List;

import jakarta.servlet.RequestDispatcher;
import jakarta.servlet.ServletException;
import jakarta.servlet.http.*;
import jakarta.servlet.annotation.*;

@WebServlet("/productList")
public class HelloServlet extends HttpServlet {




    public void doGet(HttpServletRequest request, HttpServletResponse response) throws IOException, ServletException {
       // model
        List<Product> products = Arrays.asList(
                new Product("product 1", 10.0),
                new Product("product 2", 20.0),
                new Product("product 3", 30.0),
                new Product("product 4", 40.0)
        );
        request.setAttribute("products", products);
        // view
        RequestDispatcher rd=request.getRequestDispatcher("productList.jsp");
        rd.forward(request, response);


    }


}

package com.example.demo3;

import java.io.*;
import java.util.Arrays;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.List;

import jakarta.servlet.RequestDispatcher;
import jakarta.servlet.ServletException;
import jakarta.servlet.http.*;
import jakarta.servlet.annotation.*;

@WebServlet("/productList")
public class HelloServlet extends HttpServlet {




    public void doGet(HttpServletRequest request, HttpServletResponse response) throws IOException, ServletException {
       // model
        List<Map<String, Object>> products = Arrays.asList(
                product("product 1", 10.0),
                product("product 2", 20.0),
                product("product 3", 30.0),
                product("product 4", 40.0)
        );
        request.setAttribute("products", products);
        // view
        RequestDispatcher rd=request.getRequestDispatcher("productList.jsp");
        rd.forward(request, response);


    }

    private Map<String, Object> product(String name, double price) {
        Map<String, Object> product = new LinkedHashMap<>();
        product.put("name", name);
        product.put("price", price);
        return product;
    }


}

package com.example.demo3.dao;

import com.example.demo3.model.Review;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;

public class ReviewDAO {
	private static final AtomicInteger NEXT_ID = new AtomicInteger(1);
	private static final Map<Integer, List<Review>> REVIEWS_BY_PRODUCT = new ConcurrentHashMap<>();

	public List<Review> findByProductId(int productId) {
		List<Review> reviews = REVIEWS_BY_PRODUCT.get(productId);
		if (reviews == null) {
			return new ArrayList<>();
		}
		return new ArrayList<>(reviews);
	}

	public Review save(int productId, String username, String comment, int rating) {
		Review review = new Review(NEXT_ID.getAndIncrement(), productId, username, comment, rating);
		REVIEWS_BY_PRODUCT.computeIfAbsent(productId, key -> new ArrayList<>()).add(review);
		return review;
	}
}

package com.example.demo3.dao;

import com.example.demo3.config.DatabaseConfig;
import com.example.demo3.model.Review;

import java.sql.*;
import java.util.ArrayList;
import java.util.List;

public class ReviewDAO {

	public List<Review> findByProductId(int productId) throws SQLException {
		List<Review> reviews = new ArrayList<>();
		String sql = "SELECT id, product_id, username, comment, rating FROM reviews WHERE product_id = ? ORDER BY created_at DESC";

		try (Connection conn = DatabaseConfig.getConnection();
		     PreparedStatement stmt = conn.prepareStatement(sql)) {
			stmt.setInt(1, productId);
			try (ResultSet rs = stmt.executeQuery()) {
				while (rs.next()) {
					Review review = new Review(
							rs.getInt("id"),
							rs.getInt("product_id"),
							rs.getString("username"),
							rs.getString("comment"),
							rs.getInt("rating")
					);
					reviews.add(review);
				}
			}
		}
		return reviews;
	}

	public Review save(int productId, String username, String comment, int rating) throws SQLException {
		String sql = "INSERT INTO reviews (product_id, username, comment, rating) VALUES (?, ?, ?, ?)";

		try (Connection conn = DatabaseConfig.getConnection();
		     PreparedStatement stmt = conn.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS)) {
			stmt.setInt(1, productId);
			stmt.setString(2, username);
			stmt.setString(3, comment);
			stmt.setInt(4, Math.max(1, Math.min(5, rating))); // Clamp rating between 1-5

			stmt.executeUpdate();

			try (ResultSet generatedKeys = stmt.getGeneratedKeys()) {
				if (generatedKeys.next()) {
					int id = generatedKeys.getInt(1);
					return new Review(id, productId, username, comment, rating);
				}
			}
		}
		throw new SQLException("Failed to create review");
	}

	public double getAverageRating(int productId) throws SQLException {
		String sql = "SELECT AVG(rating) as avg_rating FROM reviews WHERE product_id = ?";

		try (Connection conn = DatabaseConfig.getConnection();
		     PreparedStatement stmt = conn.prepareStatement(sql)) {
			stmt.setInt(1, productId);
			try (ResultSet rs = stmt.executeQuery()) {
				if (rs.next()) {
					double avg = rs.getDouble("avg_rating");
					return Double.isNaN(avg) ? 0.0 : avg;
				}
			}
		}
		return 0.0;
	}

	public int getReviewCount(int productId) throws SQLException {
		String sql = "SELECT COUNT(*) as count FROM reviews WHERE product_id = ?";

		try (Connection conn = DatabaseConfig.getConnection();
		     PreparedStatement stmt = conn.prepareStatement(sql)) {
			stmt.setInt(1, productId);
			try (ResultSet rs = stmt.executeQuery()) {
				if (rs.next()) {
					return rs.getInt("count");
				}
			}
		}
		return 0;
	}
}
